/// Bilinearly samples the exact 3D model terrain height at world coordinates (x, z).
pub fn sample_terrain_height(x: f32, z: f32) -> f32 {
    let fx = ((x - TERRAIN_X_MIN) / TERRAIN_STEP).clamp(0.0, (TERRAIN_NX - 1) as f32);
    let fz = ((z - TERRAIN_Z_MIN) / TERRAIN_STEP).clamp(0.0, (TERRAIN_NZ - 1) as f32);

    let ix0 = (fx.floor() as usize).min(TERRAIN_NX - 1);
    let iz0 = (fz.floor() as usize).min(TERRAIN_NZ - 1);
    let ix1 = (ix0 + 1).min(TERRAIN_NX - 1);
    let iz1 = (iz0 + 1).min(TERRAIN_NZ - 1);

    let tx = fx - (ix0 as f32);
    let tz = fz - (iz0 as f32);

    let h00 = TERRAIN_HEIGHTS[ix0 * TERRAIN_NZ + iz0];
    let h01 = TERRAIN_HEIGHTS[ix0 * TERRAIN_NZ + iz1];
    let h10 = TERRAIN_HEIGHTS[ix1 * TERRAIN_NZ + iz0];
    let h11 = TERRAIN_HEIGHTS[ix1 * TERRAIN_NZ + iz1];

    let h0 = h00 + (h01 - h00) * tz;
    let h1 = h10 + (h11 - h10) * tz;
    h0 + (h1 - h0) * tx
}
